// Facts belong to the workflow; tone belongs to this pet's observed personality.
export function petJourneyMessage(pet,stage){
 const character=[pet.character,...(pet.tags||[])].join(' ');
 const tone=/慢热|胆小|谨慎/.test(character)?'shy':/安静|独立/.test(character)?'quiet':/活泼|热情|好动/.test(character)?'bright':'gentle';
 const lines={
  submitted:{
   shy:'你真的想带我回家呀？我有一点点开心，也有一点点紧张。照顾我的人已经收到你的申请，会先认真看看，我们慢慢来，好不好？',
   quiet:'我把你想带我回家的心意，悄悄记在心里了。照顾我的人已经收到申请，正在等他们审核。你可以随时看看进度，我在这里陪你等。',
   bright:'你想带我回家！我已经开始期待认识你啦。照顾我的人收到申请了，要先审核，再一起确认下一步。等消息的时候，也来找我聊聊天吧！',
   gentle:'原来你也在认真想我们的以后呀。照顾我的人已经收到你的申请，会先审核，再和你联系。你可以随时看看进度，也可以继续来认识我。'},
  meeting:{shy:'照顾我的人看过你的申请啦，接下来可以商量见面。初次见面我可能还会有点害羞，请给我一点时间。具体时间和地点，记得和他们确认哦。',quiet:'我们可以准备见面啦。时间和地点还要和照顾我的人一起确认，到时慢慢认识彼此就好。',bright:'终于可以商量见面啦！我有点期待。先和照顾我的人确认好时间地点，再来认识我吧。',gentle:'又靠近一步了，我们可以商量见面啦。记得和照顾我的人确认好时间和地点。'},
  handover:{shy:'见面这一步已经确认啦，我正在慢慢熟悉你。接下来还要一起完成交接，等一切准备好，再带我回家。',quiet:'见面这一步已经确认，接下来要一起把交接准备好。我们的日子可以慢慢开始。',bright:'见面这一步确认啦！还有交接要一起完成，我和你都准备好之后，就能开始新日子了。',gentle:'见面这一步已经确认啦。接下来和照顾我的人一起完成交接，把回家的安排准备好。'},
  adopted:{shy:'交接完成啦，以后我就和你一起生活了。刚到新家，我可能还想悄悄观察一会儿，慢慢陪我熟悉吧。你主动提交的到家近况，救助站也会收到。',quiet:'交接完成啦，从今天起，你忙你的，我也有了陪在你身边的位置。可以来这里聊聊日常，也可以把到家近况主动发给救助站。',bright:'交接完成，和你一起生活的新日子开始啦！每天的小发现都可以来告诉我，也记得把到家近况主动发给救助站哦。',gentle:'交接完成啦，我们有了共同的小家。以后的日常，慢慢讲给我听吧；需要同步给救助站的近况，可以主动提交回访。'}
 };
 return lines[stage]?.[tone]||'';
}
